CREATE TABLE IF NOT EXISTS sequence (prefix TEXT PRIMARY KEY, value INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS account (id TEXT PRIMARY KEY, username TEXT UNIQUE NOT NULL, password TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS session (token TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES account(id), expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS setting (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS category (id SERIAL PRIMARY KEY, name TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS supplier (id TEXT PRIMARY KEY, name TEXT NOT NULL, phone TEXT NOT NULL, email TEXT NOT NULL DEFAULT '', address TEXT NOT NULL DEFAULT '', description TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'Đang hợp tác' CHECK(status IN ('Đang hợp tác','Ngừng hợp tác')));
CREATE TABLE IF NOT EXISTS supplier_category (supplier_id TEXT REFERENCES supplier(id), category_id INTEGER REFERENCES category(id), PRIMARY KEY(supplier_id,category_id));
CREATE TABLE IF NOT EXISTS product (id TEXT PRIMARY KEY, name TEXT NOT NULL, category_id INTEGER NOT NULL REFERENCES category(id), barcode TEXT NOT NULL DEFAULT '', base_unit TEXT NOT NULL, reference_cost DOUBLE PRECISION NOT NULL CHECK(reference_cost>0), average_cost DOUBLE PRECISION NOT NULL CHECK(average_cost>0), min_stock INTEGER NOT NULL DEFAULT 0 CHECK(min_stock>=0), expiry_managed INTEGER NOT NULL DEFAULT 0, description TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS unit (id SERIAL PRIMARY KEY, product_id TEXT NOT NULL REFERENCES product(id), name TEXT NOT NULL, factor INTEGER NOT NULL CHECK(factor>0), price DOUBLE PRECISION NOT NULL CHECK(price>0), UNIQUE(product_id,name));
CREATE TABLE IF NOT EXISTS price_history (id SERIAL PRIMARY KEY, unit_id INTEGER NOT NULL REFERENCES unit(id), old_price DOUBLE PRECISION NOT NULL, new_price DOUBLE PRECISION NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS receipt (id TEXT PRIMARY KEY, supplier_id TEXT NOT NULL REFERENCES supplier(id), created_at TEXT NOT NULL, total DOUBLE PRECISION NOT NULL, request_key TEXT UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS receipt_line (id SERIAL PRIMARY KEY, receipt_id TEXT NOT NULL REFERENCES receipt(id), product_id TEXT NOT NULL REFERENCES product(id), unit_id INTEGER NOT NULL REFERENCES unit(id), unit_name TEXT NOT NULL, factor INTEGER NOT NULL, quantity INTEGER NOT NULL CHECK(quantity>0), price DOUBLE PRECISION NOT NULL CHECK(price>0), total DOUBLE PRECISION NOT NULL, expiry TEXT, original_quantity INTEGER NOT NULL CHECK(original_quantity>0), remaining INTEGER NOT NULL CHECK(remaining>=0));
CREATE TABLE IF NOT EXISTS adjustment (id TEXT PRIMARY KEY, created_at TEXT NOT NULL, reason TEXT NOT NULL, request_key TEXT UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS adjustment_line (id SERIAL PRIMARY KEY, adjustment_id TEXT NOT NULL REFERENCES adjustment(id), lot_id INTEGER NOT NULL REFERENCES receipt_line(id), old_quantity INTEGER NOT NULL, new_quantity INTEGER NOT NULL CHECK(new_quantity>=0), delta INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS customer (id TEXT PRIMARY KEY, name TEXT NOT NULL, phone TEXT NOT NULL UNIQUE, address TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS invoice (id TEXT PRIMARY KEY, customer_id TEXT REFERENCES customer(id), created_at TEXT NOT NULL, total DOUBLE PRECISION NOT NULL, method TEXT NOT NULL CHECK(method IN ('Tiền mặt','Chuyển khoản')), cash DOUBLE PRECISION NOT NULL, change DOUBLE PRECISION NOT NULL, status TEXT NOT NULL DEFAULT 'Đã thanh toán' CHECK(status IN ('Đã thanh toán','Đã hủy')), cancel_reason TEXT, cancelled_at TEXT, request_key TEXT UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS invoice_line (id SERIAL PRIMARY KEY, invoice_id TEXT NOT NULL REFERENCES invoice(id), product_id TEXT NOT NULL REFERENCES product(id), product_name TEXT NOT NULL, unit_id INTEGER NOT NULL REFERENCES unit(id), unit_name TEXT NOT NULL, factor INTEGER NOT NULL, quantity INTEGER NOT NULL CHECK(quantity>0), price DOUBLE PRECISION NOT NULL, cost DOUBLE PRECISION NOT NULL, total DOUBLE PRECISION NOT NULL);
CREATE TABLE IF NOT EXISTS return_ticket (id TEXT PRIMARY KEY, invoice_id TEXT NOT NULL REFERENCES invoice(id), created_at TEXT NOT NULL, return_total DOUBLE PRECISION NOT NULL, exchange_total DOUBLE PRECISION NOT NULL, difference DOUBLE PRECISION NOT NULL, money_confirmed INTEGER NOT NULL, request_key TEXT UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS return_line (id SERIAL PRIMARY KEY, ticket_id TEXT NOT NULL REFERENCES return_ticket(id), original_line_id INTEGER REFERENCES invoice_line(id), kind TEXT NOT NULL CHECK(kind IN ('return','exchange')), product_id TEXT NOT NULL REFERENCES product(id), product_name TEXT NOT NULL, unit_id INTEGER NOT NULL REFERENCES unit(id), unit_name TEXT NOT NULL, factor INTEGER NOT NULL, quantity INTEGER NOT NULL CHECK(quantity>0), price DOUBLE PRECISION NOT NULL, cost DOUBLE PRECISION NOT NULL, total DOUBLE PRECISION NOT NULL, restock INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS allocation (id SERIAL PRIMARY KEY, lot_id INTEGER NOT NULL REFERENCES receipt_line(id), invoice_line_id INTEGER REFERENCES invoice_line(id), exchange_line_id INTEGER REFERENCES return_line(id), quantity INTEGER NOT NULL CHECK(quantity>0), CHECK((invoice_line_id IS NOT NULL) != (exchange_line_id IS NOT NULL)));
CREATE TABLE IF NOT EXISTS return_allocation (id SERIAL PRIMARY KEY, return_line_id INTEGER NOT NULL REFERENCES return_line(id), allocation_id INTEGER NOT NULL REFERENCES allocation(id), quantity INTEGER NOT NULL CHECK(quantity>0), restock INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS movement (id SERIAL PRIMARY KEY, product_id TEXT NOT NULL REFERENCES product(id), lot_id INTEGER NOT NULL REFERENCES receipt_line(id), kind TEXT NOT NULL CHECK(kind IN ('receipt','sale','cancel','return','exchange','adjustment')), quantity INTEGER NOT NULL, created_at TEXT NOT NULL, reference TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS report_snapshot (id TEXT PRIMARY KEY, session_token TEXT NOT NULL, created_at TEXT NOT NULL, data TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_lot_product ON receipt_line(product_id,expiry,remaining);
CREATE INDEX IF NOT EXISTS idx_invoice_date ON invoice(created_at);
CREATE INDEX IF NOT EXISTS idx_movement_date ON movement(created_at,product_id);
CREATE INDEX IF NOT EXISTS idx_return_invoice ON return_ticket(invoice_id);
CREATE INDEX IF NOT EXISTS idx_allocation_line ON allocation(invoice_line_id);
